select a.id, a.project_id 'project.id', a.monomer_id 'monomer.id', a.area_id 'area.id', a.factory_id 'factory.id', a.workshop_id 'workshop.id', a.production_line_id 'production_line.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'area.name', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', a.product_id, a.product_type, a.product_process_id, a.scheduling_quantity, a.task_quantity, a.complete_quantity, a.ask_complete_time, a.complete_time, a.STATUS, a.issue_status, product.serial_number serial_number, product.bool_abnormal_enum,
product.plate plate, product.`name`, product.color,
product.specification specification, product.`name`, material,
