date(a.create_time) <=date(#{endDate})

SELECT date_format(a.create_time, '%Y-%m-%d') date,
SUM( a.scheduling_quantity ) total_scheduling_quantity,
SUM( a.scheduling_quantity * b.length ) total_scheduling_length ,
SUM( a.scheduling_quantity * b.net_weight ) total_scheduling_net_weight,
SUM( a.task_quantity ) total_task_quantity,
SUM( a.task_quantity * b.length ) total_task_length,
SUM( a.task_quantity * b.net_weight ) total_task_net_weight,
SUM( a.complete_quantity ) total_complete_quantity,
SUM( a.complete_quantity * b.length ) total_complete_length,
SUM( a.complete_quantity * b.net_weight ) total_complete_net_weight
FROM
mes_building_scheduling a
LEFT JOIN tech_assemble b
ON a.product_id=b.id

    a.bool_delete_enum= FALSE
    AND
    date_format( a.create_time, '%Y-%m' )= date_format( #{date}, '%Y-%m' )
    
        AND a.factory_id = #{factoryId}
    
    
        AND a.workshop_id = #{workshopId}
    
    
        AND a.production_line_id = #{productionLineId}
    
    
    
        AND a.monomer_id = #{monomerId}
    
    
        AND a.area_id = #{areaId}
    
    AND a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()}
    
        AND a.project_id in
        
            #{projectId}
        
    
    
        AND a.project_id=#{projectId}
    

GROUP BY date;

