SELECT a.* from ( SELECT a.create_time, a.update_time, a.bool_delete_enum, a.version, a.id, a.project_id, a.monomer_id, a.area_id, a.bool_status_enum, a.NAME, a.serial_number, a.specification, a.length, a.material, a.quantity, a.net_weight, a.total_net_weight, a.gross_weight, a.total_gross_weight, a.surface_area, a.drawing_number, a.remark, a.business_id, a.bool_abnormal_enum, cp.`name` project_name, pm.`name` monomer_name, pd.`name` Area_name, IFNULL(b.produced_quantity, 0 ) produced_quantity, IFNULL(b.total_task_quantity, 0 ) total_task_quantity, IFNULL(b.total_scheduling_quantity, 0 ) total_scheduling_quantity FROM tech_artifact a LEFT JOIN ( SELECT product_id, SUM( complete_quantity ) produced_quantity, SUM( task_quantity ) total_task_quantity, SUM( scheduling_quantity ) total_scheduling_quantity FROM mes_building_scheduling WHERE product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} AND bool_delete_enum = 0 GROUP BY product_id ) AS b ON a.id = b.product_id LEFT JOIN contract_project cp ON cp.id =a.project_id LEFT JOIN plan_monomer pm ON pm.id =a.monomer_id LEFT JOIN plan_area pd ON pd.id =a.area_id
