SELECT * from (
SELECT
a.id,a. project_id, a.monomer_id, a.area_id, a.bool_status_enum, a.category, a.name, a.serial_number,a.bool_abnormal_enum,
cp.`name` project_name,pm.`name` monomer_name,pd.`name` Area_name,
