LEFT JOIN contract_project cp ON cp.id =a.project_id
LEFT JOIN plan_monomer pm ON pm.id =a.monomer_id
LEFT JOIN plan_area pd ON pd.id =a.area_id

    a.bool_delete_enum=FALSE
    
