SELECT a.steel_spec, a.steel_id, steel.`name`, ifnull( sum( a.quantity ), 0 ) quantity, ifnull( sum( a.quantity * a.net_weight ), 0 ) total_net_weight, ifnull( sum( a.quantity * a.gross_weight ), 0 ) total_gross_weight , ifnull( sum( b.total_scheduling_quantity ), 0 ) total_scheduling_quantity, ifnull( sum( b.total_scheduling_quantity * a.net_weight ), 0 ) total_scheduling_net_weight, ifnull( sum( b.total_scheduling_quantity * a.gross_weight ), 0 ) total_scheduling_gross_weight from tech_machine_part a left join ( select product_id, sum( scheduling_quantity ) total_scheduling_quantity from mes_building_scheduling where bool_delete_enum = false and product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()} group by product_id ) as b on a.id = b.product_id left join sys_steel_classification steel on steel.id = a.steel_id
