AND a.bool_abnormal_enum = #{boolAbnormalEnum}
AND a. monomer_id = #{ monomerId}
AND a.project_id = #{projectId}
AND a.area_id IN
#{areaId}
GROUP BY a.steel_id, a.steel_spec, steel.`name` ORDER BY a.steel_spec IS NULL ,case WHEN a.steel_spec like '%*%' then 2 ELSE 1 end ,a.steel_spec*1

